// Writes plugins/model-coach/hooks/catalog-data.ts from catalog.json, so the
// mod ships a bundled copy (hooks modules cannot import JSON).
// Usage: node scripts/build-catalog.mjs [--check]
import { readFileSync, writeFileSync } from 'node:fs'

const root = new URL('../plugins/model-coach/', import.meta.url)
const json = JSON.parse(readFileSync(new URL('catalog.json', root), 'utf8'))
const out =
  '// Generated by scripts/build-catalog.mjs from catalog.json. Do not edit.\n' +
  "import type { Catalog } from './catalog'\n\n" +
  `export const BUNDLED_CATALOG: Catalog = ${JSON.stringify(json, null, 2)}\n`
const target = new URL('hooks/catalog-data.ts', root)

if (process.argv.includes('--check')) {
  if (readFileSync(target, 'utf8') !== out) {
    console.error('catalog-data.ts is out of date: run node scripts/build-catalog.mjs')
    process.exit(1)
  }
  console.log('catalog-data.ts is in sync')
} else {
  writeFileSync(target, out)
  console.log('wrote', target.pathname)
}
